$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$mp=Join-Path $root 'port-changes.json';$m=Get-Content $mp -Raw|ConvertFrom-Json
$targets=@(
 [pscustomobject]@{rel='AllBlockEntityTypes.java';changes=@([pscustomobject]@{from="import com.simibubi.create.content.kinetics.chainConveyor.ChainConveyorVisual;`n";to=''},[pscustomobject]@{from="import com.simibubi.create.content.logistics.packager.PackagerVisual;`n";to=''},[pscustomobject]@{from="import com.simibubi.create.content.logistics.packagePort.frogport.FrogportVisual;`n";to=''});status='Unused newer-Flywheel visual imports removed; native renderer registrations retained.'},
 [pscustomobject]@{rel='AllEntityTypes.java';changes=@([pscustomobject]@{from="import com.simibubi.create.content.logistics.box.PackageVisual;`n";to=''});status='Unused newer-Flywheel package visual import removed; Package renderer/entity registration retained.'},
 [pscustomobject]@{rel='content/logistics/packagePort/PackagePortTargetSelectionHandler.java';changes=@([pscustomobject]@{from='import com.simibubi.create.AllBlocks;';to="import com.simibubi.create.AllBlocks;`nimport com.simibubi.create.CreateClient;"},[pscustomobject]@{from='import com.simibubi.create.foundation.outliner.Outliner;';to=''},[pscustomobject]@{from='Outliner.getInstance()';to='CreateClient.OUTLINER'});status='Original Frogport/postbox target outlines retained through the Fabric baseline CreateClient outliner.'},
 [pscustomobject]@{rel='content/logistics/packagerLink/LogisticallyLinkedClientHandler.java';changes=@([pscustomobject]@{from='import com.simibubi.create.content.logistics.factoryBoard.FactoryPanelBehaviour;';to="import com.simibubi.create.CreateClient;`nimport com.simibubi.create.content.logistics.factoryBoard.FactoryPanelBehaviour;"},[pscustomobject]@{from='import com.simibubi.create.foundation.outliner.Outliner;';to=''},[pscustomobject]@{from='Outliner.getInstance()';to='CreateClient.OUTLINER'});status='Original linked-network outlines retained through the Fabric baseline CreateClient outliner.'},
 [pscustomobject]@{rel='content/kinetics/chainConveyor/ChainConveyorShape.java';changes=@([pscustomobject]@{from='.rotateYDegrees(';to='.rotateY('});status='Original chain hitbox geometry retained through the Fabric transform API.'}
)
foreach($t in $targets){$p=Join-Path $root "source/fabric/src/main/java/com/simibubi/create/$($t.rel)";$x=[IO.File]::ReadAllText($p);foreach($c in $t.changes){if(-not$x.Contains($c.from)){throw "Cleanup anchor missing in $($t.rel): $($c.from)"};$x=$x.Replace($c.from,$c.to)};[IO.File]::WriteAllText($p,$x,[Text.UTF8Encoding]::new($false));$e=$m.files|Where-Object path -eq $t.rel;$e.changes=@($e.changes)+$t.changes;$e.status=$t.status};$m|ConvertTo-Json -Depth 20|Set-Content $mp -Encoding utf8;Write-Output 'Cleaned registration imports and restored baseline target-selection outliners.'
